CREATE TABLE public.life_rules (id text PRIMARY KEY, title text NOT NULL, duration_minutes integer NOT NULL DEFAULT 30 CHECK(duration_minutes>0), energy_cost integer NOT NULL DEFAULT 0 CHECK(energy_cost>=0), energy_gain integer NOT NULL DEFAULT 0 CHECK(energy_gain>=0), money_cost integer NOT NULL DEFAULT 0 CHECK(money_cost>=0), progression_gain integer NOT NULL DEFAULT 0, allowed_kinds text[] NOT NULL DEFAULT '{}');
GRANT SELECT ON public.life_rules TO authenticated; GRANT ALL ON public.life_rules TO service_role; ALTER TABLE public.life_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY "rules read" ON public.life_rules FOR SELECT TO authenticated USING(true);
INSERT INTO public.life_rules VALUES ('rest','Se reposer',30,0,25,0,0,ARRAY['logement']),('eat','Manger',20,0,10,8,0,ARRAY['cafe','commerce','logement']),('study','Étudier',60,12,0,0,5,ARRAY['universite','logement']),('course','Assister au cours',120,20,0,0,15,ARRAY['universite']),('work','Travailler',240,30,0,0,10,ARRAY['entreprise','commerce','administration']),('transport','Transport public',10,0,0,2,0,ARRAY['gare','station']);
CREATE TABLE public.life_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), max_energy integer NOT NULL DEFAULT 100 CHECK(max_energy=100), response_minutes integer NOT NULL DEFAULT 1, work_start integer NOT NULL DEFAULT 8, work_end integer NOT NULL DEFAULT 18, course_start integer NOT NULL DEFAULT 9, course_end integer NOT NULL DEFAULT 17, paid_shifts_month integer NOT NULL DEFAULT 20);
GRANT SELECT ON public.life_settings TO authenticated; GRANT ALL ON public.life_settings TO service_role; ALTER TABLE public.life_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY "settings read" ON public.life_settings FOR SELECT TO authenticated USING(true); INSERT INTO public.life_settings(id) VALUES(1);
CREATE TABLE public.study_fields (id text PRIMARY KEY,name text NOT NULL,description text NOT NULL DEFAULT '',skill text NOT NULL);
GRANT SELECT ON public.study_fields TO authenticated; GRANT ALL ON public.study_fields TO service_role; ALTER TABLE public.study_fields ENABLE ROW LEVEL SECURITY; CREATE POLICY "fields read" ON public.study_fields FOR SELECT TO authenticated USING(true);
INSERT INTO public.study_fields VALUES ('law','Droit','Institutions, droit public et raisonnement juridique.','Raisonnement juridique'),('economics','Économie','Marchés, politiques économiques et analyse.','Analyse économique'),('politics','Sciences politiques','Institutions et vie citoyenne.','Analyse politique'),('journalism','Journalisme','Enquête, information et expression.','Rédaction'),('business','Commerce','Relation client et gestion.','Négociation'),('computing','Informatique','Programmation et systèmes numériques.','Programmation');
ALTER TABLE public.jobs ADD COLUMN location_id uuid REFERENCES public.locations(id), ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN required_skill text NOT NULL DEFAULT '', ADD COLUMN skill_min integer NOT NULL DEFAULT 0;
INSERT INTO public.jobs(title,city_id,salary,min_age,location_id,description,required_skill,skill_min)
SELECT v.title,l.city_id,v.salary,18,l.id,v.description,v.skill,v.minimum FROM public.locations l JOIN (VALUES ('Assistant administratif','administration',1600,'Accueil et suivi des dossiers.','',0),('Vendeur','commerce',1500,'Accueil et conseil en boutique.','',0),('Assistant commercial','entreprise',1800,'Suivi des clients et des ventes.','',0),('Journaliste junior','entreprise',1900,'Préparation de sujets et rédaction.','Rédaction',15),('Développeur junior','entreprise',2200,'Développement des outils numériques.','Programmation',15),('Assistant juridique','administration',1900,'Préparation des dossiers juridiques.','Raisonnement juridique',15)) v(title,kind,salary,description,skill,minimum) ON l.kind=v.kind WHERE l.district_id IS NOT NULL;
CREATE TABLE public.study_enrollments (character_id uuid PRIMARY KEY REFERENCES public.characters(id),field_id text NOT NULL REFERENCES public.study_fields(id),location_id uuid NOT NULL REFERENCES public.locations(id),progress integer NOT NULL DEFAULT 0,skills jsonb NOT NULL DEFAULT '{}',semester integer NOT NULL DEFAULT 1,enrolled_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.study_enrollments TO authenticated; GRANT ALL ON public.study_enrollments TO service_role; ALTER TABLE public.study_enrollments ENABLE ROW LEVEL SECURITY; CREATE POLICY "own studies" ON public.study_enrollments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.job_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id),job_id uuid NOT NULL REFERENCES public.jobs(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','rejected')),applied_at timestamptz NOT NULL,response_at timestamptz NOT NULL, UNIQUE(character_id,job_id));
GRANT SELECT ON public.job_applications TO authenticated; GRANT ALL ON public.job_applications TO service_role; ALTER TABLE public.job_applications ENABLE ROW LEVEL SECURITY; CREATE POLICY "own applications" ON public.job_applications FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.employments (character_id uuid PRIMARY KEY REFERENCES public.characters(id),job_id uuid NOT NULL REFERENCES public.jobs(id),status text NOT NULL DEFAULT 'active',started_at timestamptz NOT NULL,progress integer NOT NULL DEFAULT 0,skills jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.employments TO authenticated; GRANT ALL ON public.employments TO service_role; ALTER TABLE public.employments ENABLE ROW LEVEL SECURITY; CREATE POLICY "own employment" ON public.employments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.housing_types (id text PRIMARY KEY,name text NOT NULL,daily_cost integer NOT NULL CHECK(daily_cost>=0));
GRANT SELECT ON public.housing_types TO authenticated; GRANT ALL ON public.housing_types TO service_role; ALTER TABLE public.housing_types ENABLE ROW LEVEL SECURITY; CREATE POLICY "housing types read" ON public.housing_types FOR SELECT TO authenticated USING(true); INSERT INTO public.housing_types VALUES('room','Chambre',10),('studio','Studio',20),('flat','Appartement',30);
CREATE TABLE public.character_housing (character_id uuid PRIMARY KEY REFERENCES public.characters(id),type_id text NOT NULL REFERENCES public.housing_types(id),location_id uuid NOT NULL REFERENCES public.locations(id),last_paid_date date);
GRANT SELECT ON public.character_housing TO authenticated; GRANT ALL ON public.character_housing TO service_role; ALTER TABLE public.character_housing ENABLE ROW LEVEL SECURITY; CREATE POLICY "own housing" ON public.character_housing FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id),type text NOT NULL REFERENCES public.life_rules(id),title text NOT NULL,start_time timestamptz NOT NULL,end_time timestamptz NOT NULL,location_id uuid NOT NULL REFERENCES public.locations(id),target_location_id uuid REFERENCES public.locations(id),energy_cost integer NOT NULL DEFAULT 0,energy_gain integer NOT NULL DEFAULT 0,money_cost integer NOT NULL DEFAULT 0,reward integer NOT NULL DEFAULT 0,progression_gain integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','running','completed','cancelled')),source_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(character_id,source_key));
GRANT SELECT ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role; ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY; CREATE POLICY "own activities" ON public.activities FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid())); CREATE INDEX activities_owner_time ON public.activities(character_id,start_time);
CREATE FUNCTION public.game_now() RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (world_date+world_time + (extract(epoch FROM (now()-clock_started_at))*time_speed)*interval '1 second') AT TIME ZONE 'UTC' FROM public.world_state WHERE id=1 $$; REVOKE ALL ON FUNCTION public.game_now() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.game_now() TO authenticated,service_role;
CREATE FUNCTION public.settle_daily_life(_character_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; a public.activities; app public.job_applications; j public.jobs; t timestamptz:=public.game_now(); field public.study_fields; accepted boolean; BEGIN
SELECT * INTO c FROM public.characters WHERE id=_character_id FOR UPDATE; IF NOT FOUND OR (auth.uid() IS DISTINCT FROM c.user_id AND current_user<>'postgres') THEN RAISE EXCEPTION 'Non autorisé'; END IF;
FOR a IN SELECT * FROM public.activities WHERE character_id=c.id AND status='running' AND end_time<=t ORDER BY end_time FOR UPDATE LOOP
 UPDATE public.characters SET energy=LEAST(100,energy+a.energy_gain),updated_at=now() WHERE id=c.id;
 IF a.reward>0 THEN UPDATE public.accounts SET balance=balance+a.reward WHERE character_id=c.id; INSERT INTO public.transactions(account_id,amount,label) SELECT id,a.reward,'Salaire — '||a.title FROM public.accounts WHERE character_id=c.id; END IF;
 IF a.type IN('study','course') THEN SELECT f.* INTO field FROM public.study_fields f JOIN public.study_enrollments e ON e.field_id=f.id WHERE e.character_id=c.id; UPDATE public.study_enrollments SET progress=progress+a.progression_gain,semester=1+(progress+a.progression_gain)/100,skills=jsonb_set(skills,ARRAY[field.skill],to_jsonb(COALESCE((skills->>field.skill)::integer,0)+a.progression_gain)) WHERE character_id=c.id; END IF;
 IF a.type='work' THEN UPDATE public.employments SET progress=progress+a.progression_gain,skills=jsonb_set(skills,ARRAY['Expérience professionnelle'],to_jsonb(COALESCE((skills->>'Expérience professionnelle')::integer,0)+a.progression_gain)) WHERE character_id=c.id; END IF;
 IF a.type='transport' AND a.target_location_id IS NOT NULL THEN UPDATE public.character_positions p SET location_id=l.id,district_id=l.district_id,updated_at=now() FROM public.locations l WHERE p.character_id=c.id AND l.id=a.target_location_id AND l.city_id=p.city_id; END IF;
 UPDATE public.activities SET status='completed' WHERE id=a.id;
END LOOP;
FOR app IN SELECT * FROM public.job_applications WHERE character_id=c.id AND status='pending' AND response_at<=t ORDER BY applied_at,id FOR UPDATE LOOP
 SELECT * INTO j FROM public.jobs WHERE id=app.job_id;
 accepted:= c.path_id IN('young_worker','early_career') AND c.age>=j.min_age AND NOT EXISTS(SELECT 1 FROM public.employments WHERE character_id=c.id) AND (j.skill_min=0 OR c.path_id='early_career' OR COALESCE((c.progression->>j.required_skill)::integer,0)>=j.skill_min);
 UPDATE public.job_applications SET status=CASE WHEN accepted THEN 'accepted' ELSE 'rejected' END WHERE id=app.id;
 IF accepted THEN INSERT INTO public.employments(character_id,job_id,started_at) VALUES(c.id,j.id,t); UPDATE public.characters SET situation=j.title WHERE id=c.id; END IF;
END LOOP;
UPDATE public.activities SET status='cancelled' WHERE character_id=c.id AND status='planned' AND end_time<=t;
END $$; REVOKE ALL ON FUNCTION public.settle_daily_life(uuid) FROM PUBLIC;
CREATE FUNCTION public.prepare_daily_life() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; t timestamptz:=public.game_now(); e public.study_enrollments; emp public.employments; j public.jobs; r public.life_rules; s public.life_settings; d date; start_at timestamptz; home uuid; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; SELECT * INTO c FROM public.characters WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personnage introuvable'; END IF;
PERFORM public.settle_daily_life(c.id); SELECT id INTO home FROM public.locations WHERE city_id=c.city_id AND kind='logement' AND district_id IS NOT NULL LIMIT 1;
INSERT INTO public.character_housing(character_id,type_id,location_id) VALUES(c.id,CASE c.path_id WHEN 'student' THEN 'room' WHEN 'young_worker' THEN 'studio' ELSE 'flat' END,home) ON CONFLICT DO NOTHING;
SELECT * INTO s FROM public.life_settings WHERE id=1; SELECT * INTO e FROM public.study_enrollments WHERE character_id=c.id; SELECT * INTO emp FROM public.employments WHERE character_id=c.id;
FOR i IN 0..6 LOOP d:=(t AT TIME ZONE 'UTC')::date+i; IF extract(isodow FROM d)<=5 THEN
 IF e.character_id IS NOT NULL THEN SELECT * INTO r FROM public.life_rules WHERE id='course'; start_at:=(d+s.course_start*interval '1 hour') AT TIME ZONE 'UTC'; IF start_at+r.duration_minutes*interval '1 minute'>t THEN INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,progression_gain,source_key) SELECT c.id,'course','Cours — '||f.name,start_at,start_at+r.duration_minutes*interval '1 minute',e.location_id,r.energy_cost,r.progression_gain,'course:'||d FROM public.study_fields f WHERE f.id=e.field_id ON CONFLICT DO NOTHING; END IF; END IF;
 IF emp.character_id IS NOT NULL THEN SELECT * INTO j FROM public.jobs WHERE id=emp.job_id; SELECT * INTO r FROM public.life_rules WHERE id='work'; start_at:=(d+s.work_start*interval '1 hour') AT TIME ZONE 'UTC'; IF start_at+r.duration_minutes*interval '1 minute'>t THEN INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,reward,progression_gain,source_key) VALUES(c.id,'work',j.title,start_at,start_at+r.duration_minutes*interval '1 minute',j.location_id,r.energy_cost,j.salary/s.paid_shifts_month,r.progression_gain,'work:'||d) ON CONFLICT DO NOTHING; END IF; END IF;
END IF; END LOOP; RETURN c.id; END $$; REVOKE ALL ON FUNCTION public.prepare_daily_life() FROM PUBLIC;
CREATE FUNCTION public.daily_life_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; result jsonb; BEGIN cid:=public.prepare_daily_life();
SELECT jsonb_build_object('world_now',public.game_now(),'character',(SELECT to_jsonb(c) FROM public.characters c WHERE id=cid),'rules',(SELECT jsonb_agg(r) FROM public.life_rules r),'settings',(SELECT to_jsonb(s) FROM public.life_settings s WHERE id=1),'fields',(SELECT jsonb_agg(f) FROM public.study_fields f),'housing_types',(SELECT jsonb_agg(h) FROM public.housing_types h),'housing',(SELECT to_jsonb(h)||jsonb_build_object('name',ty.name,'daily_cost',ty.daily_cost,'location',to_jsonb(l)) FROM public.character_housing h JOIN public.housing_types ty ON ty.id=h.type_id JOIN public.locations l ON l.id=h.location_id WHERE h.character_id=cid),'enrollment',(SELECT to_jsonb(e)||jsonb_build_object('field_name',f.name,'skill',f.skill,'location',to_jsonb(l)) FROM public.study_enrollments e JOIN public.study_fields f ON f.id=e.field_id JOIN public.locations l ON l.id=e.location_id WHERE e.character_id=cid),'employment',(SELECT to_jsonb(e)||jsonb_build_object('job',to_jsonb(j),'location',to_jsonb(l)) FROM public.employments e JOIN public.jobs j ON j.id=e.job_id JOIN public.locations l ON l.id=j.location_id WHERE e.character_id=cid),'offers',COALESCE((SELECT jsonb_agg(to_jsonb(j)||jsonb_build_object('location',to_jsonb(l),'employer','Services de '||ci.name)) FROM public.jobs j JOIN public.locations l ON l.id=j.location_id JOIN public.cities ci ON ci.id=j.city_id WHERE j.city_id=(SELECT city_id FROM public.characters WHERE id=cid)),'[]'::jsonb),'applications',COALESCE((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('job_title',j.title)) FROM public.job_applications a JOIN public.jobs j ON j.id=a.job_id WHERE a.character_id=cid),'[]'::jsonb),'activities',COALESCE((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('location',to_jsonb(l)) ORDER BY a.start_time) FROM public.activities a JOIN public.locations l ON l.id=a.location_id WHERE a.character_id=cid AND a.start_time>public.game_now()-interval '7 days'),'[]'::jsonb),'position',(SELECT to_jsonb(p) FROM public.character_positions p WHERE character_id=cid)) INTO result; RETURN result; END $$; REVOKE ALL ON FUNCTION public.daily_life_state() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_life_state() TO authenticated;
CREATE FUNCTION public.enroll_studies(_field_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; lid uuid; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; IF c.path_id<>'student' THEN RAISE EXCEPTION 'Réservé au parcours Étudiant'; END IF; IF NOT EXISTS(SELECT 1 FROM public.study_fields WHERE id=_field_id) THEN RAISE EXCEPTION 'Filière inconnue'; END IF; SELECT id INTO lid FROM public.locations WHERE city_id=c.city_id AND kind='universite' AND accessible AND district_id IS NOT NULL LIMIT 1; IF lid IS NULL THEN RAISE EXCEPTION 'Université indisponible'; END IF; INSERT INTO public.study_enrollments(character_id,field_id,location_id) VALUES(cid,_field_id,lid); UPDATE public.characters SET situation='Étudiant — '||(SELECT name FROM public.study_fields WHERE id=_field_id) WHERE id=cid; PERFORM public.prepare_daily_life(); END $$; REVOKE ALL ON FUNCTION public.enroll_studies(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.enroll_studies(text) TO authenticated;
CREATE FUNCTION public.apply_job(_job_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; j public.jobs; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; IF c.path_id NOT IN('young_worker','early_career') THEN RAISE EXCEPTION 'Réservé aux parcours professionnels'; END IF; IF EXISTS(SELECT 1 FROM public.employments WHERE character_id=cid) THEN RAISE EXCEPTION 'Vous avez déjà un emploi'; END IF; SELECT * INTO j FROM public.jobs WHERE id=_job_id AND city_id=c.city_id AND location_id IS NOT NULL; IF NOT FOUND OR c.age<j.min_age THEN RAISE EXCEPTION 'Offre inaccessible'; END IF; INSERT INTO public.job_applications(character_id,job_id,applied_at,response_at) VALUES(cid,j.id,public.game_now(),public.game_now()+(SELECT response_minutes FROM public.life_settings WHERE id=1)*interval '1 minute'); END $$; REVOKE ALL ON FUNCTION public.apply_job(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.apply_job(uuid) TO authenticated;
CREATE FUNCTION public.start_life_activity(_type text DEFAULT NULL,_activity_id uuid DEFAULT NULL,_target_location_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; p public.character_positions; l public.locations; target public.locations; a public.activities; r public.life_rules; t timestamptz:=public.game_now(); acc public.accounts; s public.life_settings; j public.jobs; id uuid; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid FOR UPDATE; SELECT * INTO p FROM public.character_positions WHERE character_id=cid; SELECT * INTO l FROM public.locations WHERE id=p.location_id; SELECT * INTO s FROM public.life_settings WHERE id=1; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status='running') THEN RAISE EXCEPTION 'Une activité est déjà en cours'; END IF;
IF _activity_id IS NOT NULL THEN SELECT * INTO a FROM public.activities WHERE id=_activity_id AND character_id=cid AND status='planned' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Activité introuvable'; END IF; SELECT * INTO r FROM public.life_rules WHERE id=a.type; IF t<a.start_time OR t+r.duration_minutes*interval '1 minute'>a.end_time THEN RAISE EXCEPTION 'Les horaires de cette activité ne permettent pas de commencer maintenant'; END IF;
ELSE SELECT * INTO r FROM public.life_rules WHERE id=_type; IF NOT FOUND OR _type='course' THEN RAISE EXCEPTION 'Action inconnue'; END IF; a.type:=r.id; a.title:=r.title; a.location_id:=l.id; a.energy_cost:=r.energy_cost; a.energy_gain:=r.energy_gain; a.money_cost:=r.money_cost; a.progression_gain:=r.progression_gain; a.reward:=0; a.start_time:=t; a.end_time:=t+r.duration_minutes*interval '1 minute'; END IF;
IF a.location_id<>p.location_id OR NOT l.accessible OR NOT l.kind=ANY(r.allowed_kinds) THEN RAISE EXCEPTION 'Rejoignez le lieu de cette activité'; END IF;
IF a.type IN('study','course') AND NOT EXISTS(SELECT 1 FROM public.study_enrollments WHERE character_id=cid) THEN RAISE EXCEPTION 'Inscrivez-vous dans une filière'; END IF;
IF a.type='work' THEN SELECT j2.* INTO j FROM public.jobs j2 JOIN public.employments e ON e.job_id=j2.id WHERE e.character_id=cid; IF NOT FOUND OR j.location_id<>l.id THEN RAISE EXCEPTION 'Rejoignez votre emploi'; END IF; IF extract(isodow FROM t AT TIME ZONE 'UTC')>5 OR extract(hour FROM t AT TIME ZONE 'UTC')<s.work_start OR extract(hour FROM (t+r.duration_minutes*interval '1 minute') AT TIME ZONE 'UTC')>s.work_end THEN RAISE EXCEPTION 'Travail du lundi au vendredi, de 08:00 à 18:00'; END IF; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND type='work' AND status IN('running','completed') AND (start_time AT TIME ZONE 'UTC')::date=(t AT TIME ZONE 'UTC')::date) THEN RAISE EXCEPTION 'Une vacation rémunérée par jour'; END IF; a.reward:=j.salary/s.paid_shifts_month; a.title:=j.title; END IF;
IF a.type='rest' AND NOT EXISTS(SELECT 1 FROM public.character_housing WHERE character_id=cid AND location_id=l.id) THEN RAISE EXCEPTION 'Rejoignez votre logement'; END IF;
IF a.type='transport' THEN SELECT * INTO target FROM public.locations WHERE id=_target_location_id AND city_id=p.city_id AND accessible AND district_id IS NOT NULL; IF NOT FOUND OR target.id=l.id OR NOT EXISTS(SELECT 1 FROM public.districts WHERE id=target.district_id AND available) THEN RAISE EXCEPTION 'Destination inaccessible'; END IF; a.target_location_id:=target.id; END IF;
IF c.energy<a.energy_cost THEN RAISE EXCEPTION 'Énergie insuffisante'; END IF; SELECT * INTO acc FROM public.accounts WHERE character_id=cid FOR UPDATE; IF NOT FOUND OR acc.balance<a.money_cost THEN RAISE EXCEPTION 'Solde insuffisant'; END IF;
IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status='planned' AND id IS DISTINCT FROM _activity_id AND start_time<a.end_time AND end_time>a.start_time) THEN RAISE EXCEPTION 'Cette activité chevauche votre agenda'; END IF;
UPDATE public.characters SET energy=energy-a.energy_cost,updated_at=now() WHERE id=cid; IF a.money_cost>0 THEN UPDATE public.accounts SET balance=balance-a.money_cost WHERE id=acc.id; INSERT INTO public.transactions(account_id,amount,label) VALUES(acc.id,-a.money_cost,a.title); END IF;
IF _activity_id IS NULL THEN INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,target_location_id,energy_cost,energy_gain,money_cost,reward,progression_gain,status) VALUES(cid,a.type,a.title,t,a.end_time,a.location_id,a.target_location_id,a.energy_cost,a.energy_gain,a.money_cost,a.reward,a.progression_gain,'running') RETURNING activities.id INTO id; ELSE UPDATE public.activities SET status='running' WHERE activities.id=a.id RETURNING activities.id INTO id; END IF; RETURN id; END $$; REVOKE ALL ON FUNCTION public.start_life_activity(text,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.start_life_activity(text,uuid,uuid) TO authenticated;
CREATE FUNCTION public.cancel_life_activity(_activity_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN cid:=public.prepare_daily_life(); UPDATE public.activities SET status='cancelled' WHERE id=_activity_id AND character_id=cid AND status='planned'; IF NOT FOUND THEN RAISE EXCEPTION 'Seules les activités prévues sont annulables'; END IF; END $$; REVOKE ALL ON FUNCTION public.cancel_life_activity(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cancel_life_activity(uuid) TO authenticated;
CREATE FUNCTION public.pay_housing() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; h public.character_housing; cost integer; acc public.accounts; d date:=(public.game_now() AT TIME ZONE 'UTC')::date; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO h FROM public.character_housing WHERE character_id=cid FOR UPDATE; IF h.last_paid_date=d THEN RAISE EXCEPTION 'Logement déjà payé aujourd’hui'; END IF; SELECT daily_cost INTO cost FROM public.housing_types WHERE id=h.type_id; SELECT * INTO acc FROM public.accounts WHERE character_id=cid FOR UPDATE; IF acc.balance<cost THEN RAISE EXCEPTION 'Solde insuffisant'; END IF; UPDATE public.accounts SET balance=balance-cost WHERE id=acc.id; INSERT INTO public.transactions(account_id,amount,label) VALUES(acc.id,-cost,'Logement — '||d); UPDATE public.character_housing SET last_paid_date=d WHERE character_id=cid; END $$; REVOKE ALL ON FUNCTION public.pay_housing() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.pay_housing() TO authenticated;
CREATE FUNCTION public.guard_busy_movement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.location_id IS DISTINCT FROM OLD.location_id AND EXISTS(SELECT 1 FROM public.activities WHERE character_id=NEW.character_id AND status='running' AND end_time>public.game_now()) THEN RAISE EXCEPTION 'Terminez votre activité avant de vous déplacer'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.guard_busy_movement() FROM PUBLIC; CREATE TRIGGER busy_movement BEFORE UPDATE ON public.character_positions FOR EACH ROW EXECUTE FUNCTION public.guard_busy_movement();